package api

import (
	"bytes"
	"encoding/json"
	"net/http"
	"reflect"
	"slices"

	"example.com/tally/internal/auth"
	"example.com/tally/internal/store"
)

// audit records, in the organization's audit log, a change that a request made. Call it only once the change has succeeded.
func (s *Server) audit(r *http.Request, p auth.Principal, action string, target store.AuditTarget) {
	s.record(r, p, action, target, nil)
}

// auditUpdate is audit for an update. Its entry lists the JSON fields whose value differs between before and after. Fields
// named in skip are left out, so secrets never enter the log.
func (s *Server) auditUpdate(r *http.Request, p auth.Principal, action string, target store.AuditTarget, before, after any, skip ...string) {
	changes := diffJSON(before, after, skip...)
	s.record(r, p, action, target, &changes)
}

func (s *Server) record(r *http.Request, p auth.Principal, action string, target store.AuditTarget, changes *map[string]store.AuditChange) {
	s.store.RecordAudit(p.OrgID, store.AuditEvent{
		Action:    action,
		Actor:     store.AuditActor{Type: "api_key", ID: p.KeyID, UserID: p.UserID},
		Target:    target,
		RequestID: RequestID(r.Context()),
		At:        s.clock.Now(),
		Changes:   changes,
	})
}

// diffJSON returns the top-level JSON fields whose value differs between before and after, with both values. A field that one
// side lacks is null on that side.
func diffJSON(before, after any, skip ...string) map[string]store.AuditChange {
	b, a := jsonObject(before), jsonObject(after)
	keys := map[string]bool{}
	for k := range b {
		keys[k] = true
	}
	for k := range a {
		keys[k] = true
	}
	changes := map[string]store.AuditChange{}
	for k := range keys {
		if slices.Contains(skip, k) || reflect.DeepEqual(b[k], a[k]) {
			continue
		}
		changes[k] = store.AuditChange{From: b[k], To: a[k]}
	}
	return changes
}

// jsonObject returns v's JSON encoding as an object. Numbers stay exact, as json.Number.
func jsonObject(v any) map[string]any {
	var m map[string]any
	b, _ := json.Marshal(v)
	dec := json.NewDecoder(bytes.NewReader(b))
	dec.UseNumber()
	_ = dec.Decode(&m)
	return m
}

func auditKey(e store.AuditEvent) cursor { return cursor{T: e.At, ID: e.ID} }

// listAuditEvents lists the organization's audit log, newest first, optionally only the entries with ?action=, ?target_id= or
// ?actor_id= (a user ID or an API key ID). Only owners and admins may read it.
func (s *Server) listAuditEvents(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	if !auth.CanManageTeam(p.Role) {
		writeJSON(w, http.StatusForbidden, map[string]string{"error": "forbidden"})
		return
	}
	pg, ok := parsePage(w, r)
	if !ok {
		return
	}
	q := r.URL.Query()
	evs := s.store.AuditEvents(p.OrgID, store.AuditFilter{Action: q.Get("action"), TargetID: q.Get("target_id"), ActorID: q.Get("actor_id")})
	items, next := pageOfNewestFirst(evs, auditKey, pg)
	writeJSON(w, http.StatusOK, list{Items: items, NextCursor: next})
}

