package api_test

import (
	"encoding/json"
	"net/http"
	"slices"
	"strings"
	"testing"
	"time"

	"example.com/tally/internal/apitest"
	"example.com/tally/internal/store"
)

type auditActor struct {
	Type   string `json:"type"`
	ID     string `json:"id"`
	UserID string `json:"user_id"`
}

type auditTarget struct {
	Type string `json:"type"`
	ID   string `json:"id"`
}

type auditChange struct {
	From any `json:"from"`
	To   any `json:"to"`
}

type auditEntry struct {
	ID        string                 `json:"id"`
	Action    string                 `json:"action"`
	Actor     auditActor             `json:"actor"`
	Target    auditTarget            `json:"target"`
	RequestID string                 `json:"request_id"`
	At        time.Time              `json:"at"`
	Changes   *map[string]auditChange `json:"changes"`
}

// listAudit answers one page of the audit log, as the key sees it.
func listAudit(t *testing.T, e *apitest.Env, key, query string) ([]auditEntry, string) {
	t.Helper()
	var out struct {
		Items      []auditEntry `json:"items"`
		NextCursor string       `json:"next_cursor"`
	}
	e.MustDo(http.StatusOK, "GET", "/v1/audit-events"+query, key, nil, &out)
	return out.Items, out.NextCursor
}

// allAudit answers the whole audit log, following the pages, newest first.
func allAudit(t *testing.T, e *apitest.Env, key, query string) []auditEntry {
	t.Helper()
	var all []auditEntry
	cursor := ""
	for {
		q := query + "&limit=100"
		if cursor != "" {
			q += "&cursor=" + cursor
		}
		items, next := listAudit(t, e, key, "?"+strings.TrimPrefix(q, "&"))
		all = append(all, items...)
		if next == "" {
			return all
		}
		cursor = next
	}
}

func keyID(t *testing.T, e *apitest.Env, token string) string {
	t.Helper()
	k, ok := e.Store.APIKeyByToken(token)
	if !ok {
		t.Fatal("no such key")
	}
	return k.ID
}

// Every one of the audited kinds is recorded once per successful request, in order, and nothing else is.
func TestAuditLogRecordsEachChange(t *testing.T) {
	e := apitest.New(t)
	key := e.Acme.Key
	var want []string

	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	want = append(want, "customer.created")
	e.MustDo(http.StatusOK, "PATCH", "/v1/customers/"+c.ID, key, map[string]any{"name": "Jane Doe", "metadata": map[string]string{"tier": "gold"}}, nil)
	want = append(want, "customer.updated")
	temp := e.CreateCustomer(e.Acme, "Temp", "temp@example.com")
	want = append(want, "customer.created")
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/customers/"+temp.ID, key, nil, nil)
	want = append(want, "customer.deleted")

	p := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	want = append(want, "plan.created")
	e.MustDo(http.StatusOK, "PATCH", "/v1/plans/"+p.ID, key, map[string]any{"name": "Team Plus"}, nil)
	want = append(want, "plan.updated")

	// Creating a subscription also creates its first invoice; only the request itself is recorded.
	c2 := e.CreateCustomer(e.Acme, "Sam", "sam@example.com")
	var sub store.Subscription
	e.MustDo(http.StatusCreated, "POST", "/v1/subscriptions", key, map[string]any{"customer_id": c2.ID, "plan_id": p.ID, "quantity": 2}, &sub)
	want = append(want, "subscription.created")
	e.MustDo(http.StatusOK, "PATCH", "/v1/subscriptions/"+sub.ID, key, map[string]any{"quantity": 3}, nil)
	want = append(want, "subscription.updated")
	e.MustDo(http.StatusOK, "POST", "/v1/subscriptions/"+sub.ID+"/cancel", key, map[string]any{"at_period_end": true}, nil)
	want = append(want, "subscription.canceled")

	var inv store.Invoice
	line := map[string]any{"lines": []map[string]any{{"description": "Setup", "quantity": 1, "unit_amount": 5000}}, "currency": "USD"}
	line["customer_id"] = c.ID
	e.MustDo(http.StatusCreated, "POST", "/v1/invoices", key, line, &inv)
	want = append(want, "invoice.created")
	e.MustDo(http.StatusOK, "POST", "/v1/invoices/"+inv.ID+"/pay", key, map[string]string{"payment_method": "pm_card_visa"}, nil)
	want = append(want, "invoice.paid")
	var second store.Invoice
	e.MustDo(http.StatusCreated, "POST", "/v1/invoices", key, line, &second)
	want = append(want, "invoice.created")
	e.MustDo(http.StatusOK, "POST", "/v1/invoices/"+second.ID+"/void", key, nil, nil)
	want = append(want, "invoice.voided")

	var ak store.APIKey
	e.MustDo(http.StatusCreated, "POST", "/v1/api-keys", key, map[string]string{"name": "CI"}, &ak)
	want = append(want, "api_key.created")
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/api-keys/"+ak.ID, key, nil, nil)
	want = append(want, "api_key.revoked")

	var inv1, inv2 store.Invite
	e.MustDo(http.StatusCreated, "POST", "/v1/invites", key, map[string]string{"email": "new@people.example", "role": "member"}, &inv1)
	want = append(want, "invite.created")
	e.MustDo(http.StatusCreated, "POST", "/v1/invites", key, map[string]string{"email": "gone@people.example", "role": "member"}, &inv2)
	want = append(want, "invite.created")
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/invites/"+inv2.ID, key, nil, nil)
	want = append(want, "invite.revoked")

	pat, _ := e.AddMember(e.Acme, "pat@acme.example", store.RoleMember)
	e.MustDo(http.StatusOK, "PATCH", "/v1/members/"+pat.ID, key, map[string]string{"role": "admin"}, nil)
	want = append(want, "member.role_changed")
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/members/"+pat.ID, key, nil, nil)
	want = append(want, "member.removed")

	var ep store.WebhookEndpoint
	e.MustDo(http.StatusCreated, "POST", "/v1/webhook-endpoints", key, map[string]any{"url": "https://hooks.acme.example/tally", "events": []string{"*"}}, &ep)
	want = append(want, "webhook_endpoint.created")
	e.MustDo(http.StatusOK, "PATCH", "/v1/webhook-endpoints/"+ep.ID, key, map[string]bool{"enabled": false}, nil)
	want = append(want, "webhook_endpoint.updated")
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/webhook-endpoints/"+ep.ID, key, nil, nil)
	want = append(want, "webhook_endpoint.deleted")

	e.MustDo(http.StatusOK, "PATCH", "/v1/org", key, map[string]string{"name": "Acme Corp"}, nil)
	want = append(want, "org.updated")

	got := allAudit(t, e, key, "?")
	actions := make([]string, 0, len(got))
	for _, en := range got {
		actions = append(actions, en.Action)
	}
	slices.Reverse(actions)
	if !slices.Equal(actions, want) {
		t.Fatalf("actions\n got %v\nwant %v", actions, want)
	}

	owner := e.Acme.Owner.ID
	kid := keyID(t, e, key)
	for _, en := range got {
		if en.Actor != (auditActor{Type: "api_key", ID: kid, UserID: owner}) {
			t.Fatalf("%s: actor %+v", en.Action, en.Actor)
		}
		if !strings.HasPrefix(en.ID, "aud_") || en.RequestID == "" || en.At.IsZero() {
			t.Fatalf("%s: entry %+v", en.Action, en)
		}
	}
	// Creates and deletes have no changes; updates always have them, possibly none.
	for _, en := range got {
		isUpdate := strings.HasSuffix(en.Action, ".updated") || en.Action == "member.role_changed" || en.Action == "org.updated"
		if isUpdate != (en.Changes != nil) {
			t.Fatalf("%s: changes %v", en.Action, en.Changes)
		}
	}
}

func TestAuditLogChanges(t *testing.T) {
	e := apitest.New(t)
	key := e.Acme.Key
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	e.MustDo(http.StatusOK, "PATCH", "/v1/customers/"+c.ID, key, map[string]any{"name": "Jane Doe", "metadata": map[string]string{"tier": "gold"}}, nil)
	e.MustDo(http.StatusOK, "PATCH", "/v1/customers/"+c.ID, key, map[string]any{"name": "Jane Doe"}, nil)
	e.MustDo(http.StatusOK, "PATCH", "/v1/org", key, map[string]string{"name": "Acme Corp"}, nil)

	entries := allAudit(t, e, key, "?action=customer.updated")
	if len(entries) != 2 {
		t.Fatalf("customer.updated entries: %+v", entries)
	}
	// Newest first: the no-op update changed nothing, so its changes are empty but present.
	if ch := entries[0].Changes; ch == nil || len(*ch) != 0 {
		t.Fatalf("no-op update changes = %v", entries[0].Changes)
	}
	ch := *entries[1].Changes
	if len(ch) != 2 || ch["name"].From != "Jane" || ch["name"].To != "Jane Doe" || ch["metadata"].From != nil || ch["metadata"].To.(map[string]any)["tier"] != "gold" {
		t.Fatalf("customer changes = %v", ch)
	}
	if _, ok := ch["email"]; ok {
		t.Fatal("an unchanged field is listed")
	}

	org := allAudit(t, e, key, "?action=org.updated")
	if len(org) != 1 || len(*org[0].Changes) != 1 || (*org[0].Changes)["name"].To != "Acme Corp" {
		t.Fatalf("org changes = %+v", org)
	}
	if org[0].Target != (auditTarget{Type: "org", ID: e.Acme.ID}) {
		t.Fatalf("org target = %+v", org[0].Target)
	}
}

func TestAuditLogNeverHoldsSecrets(t *testing.T) {
	e := apitest.New(t)
	key := e.Acme.Key
	var ak store.APIKey
	e.MustDo(http.StatusCreated, "POST", "/v1/api-keys", key, map[string]string{"name": "CI"}, &ak)
	var inv store.Invite
	e.MustDo(http.StatusCreated, "POST", "/v1/invites", key, map[string]string{"email": "new@people.example", "role": "member"}, &inv)
	token, _ := e.Store.Invite(e.Acme.ID, inv.ID)
	var ep store.WebhookEndpoint
	e.MustDo(http.StatusCreated, "POST", "/v1/webhook-endpoints", key, map[string]any{"url": "https://hooks.acme.example/tally", "events": []string{"*"}}, &ep)
	e.MustDo(http.StatusOK, "PATCH", "/v1/webhook-endpoints/"+ep.ID, key, map[string]string{"url": "https://hooks.acme.example/other"}, nil)
	e.MustDo(http.StatusOK, "PATCH", "/v1/webhook-endpoints/"+ep.ID, key, map[string]bool{"enabled": false}, nil)

	raw := e.Do("GET", "/v1/audit-events?limit=100", key, nil).Body
	for _, secret := range []string{ak.Token, token.Token, ep.Secret, key} {
		if strings.Contains(string(raw), secret) {
			t.Fatalf("the audit log holds a secret: %s", raw)
		}
	}
	entries := allAudit(t, e, key, "?action=webhook_endpoint.updated")
	if len(entries) != 2 {
		t.Fatalf("entries = %+v", entries)
	}
	for _, en := range entries {
		if _, ok := (*en.Changes)["secret"]; ok {
			t.Fatalf("secret in changes: %+v", en)
		}
	}
	if _, ok := (*entries[1].Changes)["url"]; !ok {
		t.Fatalf("url change missing: %+v", entries[1])
	}
}

func TestAuditLogRecordsNothingForFailures(t *testing.T) {
	e := apitest.New(t)
	key := e.Acme.Key
	_, viewer := e.AddMember(e.Acme, "viewer@acme.example", store.RoleViewer)
	before := len(allAudit(t, e, key, "?"))

	failing := []struct {
		name, method, path, key string
		body                    any
		code                    int
	}{
		{"invalid customer", "POST", "/v1/customers", key, map[string]string{"name": "X", "email": "nope"}, http.StatusUnprocessableEntity},
		{"no such customer", "PATCH", "/v1/customers/cus_nope", key, map[string]string{"name": "X"}, http.StatusNotFound},
		{"no such member", "DELETE", "/v1/members/usr_nope", key, nil, http.StatusNotFound},
		{"invoice without lines", "POST", "/v1/invoices", key, map[string]any{"customer_id": "cus_nope", "currency": "USD"}, http.StatusUnprocessableEntity},
		{"viewer write", "POST", "/v1/customers", viewer, map[string]string{"name": "X", "email": "x@example.com"}, http.StatusForbidden},
	}
	for _, f := range failing {
		if r := e.Do(f.method, f.path, f.key, f.body); r.Code != f.code {
			t.Fatalf("%s: %s", f.name, r)
		}
	}

	// Another organization's endpoint is not found, and stays.
	var globexEP store.WebhookEndpoint
	e.MustDo(http.StatusCreated, "POST", "/v1/webhook-endpoints", e.Globex.Key, map[string]any{"url": "https://hooks.globex.example/tally", "events": []string{"*"}}, &globexEP)
	if r := e.Do("DELETE", "/v1/webhook-endpoints/"+globexEP.ID, key, nil); r.Code != http.StatusNotFound {
		t.Fatalf("delete another organization's endpoint: %s", r)
	}
	if _, ok := e.Store.WebhookEndpoint(e.Globex.ID, globexEP.ID); !ok {
		t.Fatal("another organization's endpoint was deleted")
	}

	if after := len(allAudit(t, e, key, "?")); after != before {
		t.Fatalf("%d entries after failures, want %d", after, before)
	}
}

func TestAuditLogIsForOwnersAndAdmins(t *testing.T) {
	e := apitest.New(t)
	e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	_, admin := e.AddMember(e.Acme, "admin@acme.example", store.RoleAdmin)
	_, member := e.AddMember(e.Acme, "member@acme.example", store.RoleMember)
	_, billing := e.AddMember(e.Acme, "billing@acme.example", store.RoleBilling)
	_, viewer := e.AddMember(e.Acme, "viewer@acme.example", store.RoleViewer)

	for _, key := range []string{member, billing, viewer} {
		r := e.Do("GET", "/v1/audit-events", key, nil)
		if r.Code != http.StatusForbidden {
			t.Fatalf("read: %s", r)
		}
		var body map[string]string
		if err := json.Unmarshal(r.Body, &body); err != nil || len(body) != 1 || body["error"] != "forbidden" {
			t.Fatalf("forbidden body = %s", r.Body)
		}
	}
	if items, _ := listAudit(t, e, admin, "?"); len(items) != 1 {
		t.Fatalf("admin sees %d entries", len(items))
	}
	if items, _ := listAudit(t, e, e.Acme.Key, "?"); len(items) != 1 {
		t.Fatalf("owner sees %d entries", len(items))
	}
	if items, _ := listAudit(t, e, e.Globex.Key, "?"); len(items) != 0 {
		t.Fatalf("another organization's owner sees %d entries", len(items))
	}
	if r := e.Do("GET", "/v1/audit-events?limit=0", e.Acme.Key, nil); r.Code != http.StatusBadRequest {
		t.Fatalf("bad limit: %s", r)
	}
}

func TestAuditLogFiltersAndPages(t *testing.T) {
	e := apitest.New(t)
	key := e.Acme.Key
	var cs []store.Customer
	for _, name := range []string{"A", "B", "C", "D", "E"} {
		cs = append(cs, e.CreateCustomer(e.Acme, name, strings.ToLower(name)+"@example.com"))
		e.Clock.Advance(time.Minute)
	}
	e.CreatePlan(e.Acme, "Team", "USD", "20.00")

	byAction, _ := listAudit(t, e, key, "?action=customer.created&limit=100")
	if len(byAction) != 5 {
		t.Fatalf("customer.created: %d entries", len(byAction))
	}
	for i, en := range byAction {
		if en.Target.ID != cs[len(cs)-1-i].ID {
			t.Fatalf("entry %d is for %s, want newest first", i, en.Target.ID)
		}
	}
	byTarget, _ := listAudit(t, e, key, "?target_id="+cs[2].ID)
	if len(byTarget) != 1 || byTarget[0].Action != "customer.created" {
		t.Fatalf("target_id: %+v", byTarget)
	}
	owner, _ := listAudit(t, e, key, "?actor_id="+e.Acme.Owner.ID+"&limit=100")
	if len(owner) != 6 {
		t.Fatalf("actor_id user: %d entries", len(owner))
	}
	byKey, _ := listAudit(t, e, key, "?actor_id="+keyID(t, e, key)+"&limit=100")
	if len(byKey) != 6 {
		t.Fatalf("actor_id key: %d entries", len(byKey))
	}
	if none, _ := listAudit(t, e, key, "?actor_id=usr_someone_else"); len(none) != 0 {
		t.Fatalf("other actor: %+v", none)
	}

	// Pages of two, newest first, cover all six entries once each.
	var paged []string
	cursor := ""
	for pages := 0; ; pages++ {
		q := "?limit=2"
		if cursor != "" {
			q += "&cursor=" + cursor
		}
		items, next := listAudit(t, e, key, q)
		if len(items) > 2 {
			t.Fatalf("page of %d", len(items))
		}
		for _, en := range items {
			paged = append(paged, en.ID)
		}
		if next == "" {
			break
		}
		cursor = next
		if pages > 10 {
			t.Fatal("paging does not end")
		}
	}
	all := allAudit(t, e, key, "?")
	if len(paged) != 6 || len(all) != 6 {
		t.Fatalf("paged %d, all %d", len(paged), len(all))
	}
	for i := range all {
		if paged[i] != all[i].ID {
			t.Fatalf("page order differs at %d", i)
		}
	}
}

