	want = append(want, "invite.created")
	e.MustDo(http.StatusCreated, "POST", "/v1/invites", key, map[string]string{"email": "gone@people.example", "role": "member"}, &gone)
	want = append(want, "invite.created")
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/invites/"+gone.ID, key, nil, nil)
	want = append(want, "invite.revoked")

	pat, _ := e.AddMember(e.Acme, "pat@acme.example", store.RoleMember)
	e.MustDo(http.StatusOK, "PATCH", "/v1/members/"+pat.ID, key, map[string]string{"role": "admin"}, nil)
