	"testing"
)

func TestAuditLog(t *testing.T) {
	s := New()
	acme, globex := "org_acme", "org_globex"
	s.RecordAudit(acme, AuditEvent{Action: "customer.created", Actor: AuditActor{Type: "api_key", ID: "key_1", UserID: "usr_1"}, Target: AuditTarget{Type: "customer", ID: "cus_1"}, At: t0})
	s.RecordAudit(acme, AuditEvent{Action: "plan.updated", Actor: AuditActor{Type: "api_key", ID: "key_2", UserID: "usr_2"}, Target: AuditTarget{Type: "plan", ID: "pln_1"}, At: t0.Add(1)})
	s.RecordAudit(globex, AuditEvent{Action: "customer.created", Actor: AuditActor{Type: "api_key", ID: "key_3", UserID: "usr_3"}, Target: AuditTarget{Type: "customer", ID: "cus_2"}, At: t0.Add(2)})
	s.RecordAudit(acme, AuditEvent{Action: "customer.created", Actor: AuditActor{Type: "api_key", ID: "key_1", UserID: "usr_1"}, Target: AuditTarget{Type: "customer", ID: "cus_3"}, At: t0})

	ids := func(evs []AuditEvent) []string {
		var out []string
		for _, e := range evs {
			out = append(out, e.Target.ID)
		}
		return out
	}
	// Newest first; entries at the same time are ordered by ID, newest first.
	if got := ids(s.AuditEvents(acme, AuditFilter{})); !reflect.DeepEqual(got, []string{"pln_1", "cus_3", "cus_1"}) {
		t.Fatalf("all of acme = %v", got)
	}
	if got := ids(s.AuditEvents(globex, AuditFilter{})); !reflect.DeepEqual(got, []string{"cus_2"}) {
		t.Fatalf("all of globex = %v", got)
	}
	if got := ids(s.AuditEvents(acme, AuditFilter{Action: "customer.created"})); !reflect.DeepEqual(got, []string{"cus_3", "cus_1"}) {
		t.Fatalf("action = %v", got)
	}
	if got := ids(s.AuditEvents(acme, AuditFilter{TargetID: "pln_1"})); !reflect.DeepEqual(got, []string{"pln_1"}) {
		t.Fatalf("target = %v", got)
	}
	if got := ids(s.AuditEvents(acme, AuditFilter{ActorID: "usr_1"})); !reflect.DeepEqual(got, []string{"cus_3", "cus_1"}) {
		t.Fatalf("actor user = %v", got)
	}
	if got := ids(s.AuditEvents(acme, AuditFilter{ActorID: "key_2"})); !reflect.DeepEqual(got, []string{"pln_1"}) {
		t.Fatalf("actor key = %v", got)
	}
	if got := s.AuditEvents(acme, AuditFilter{ActorID: "usr_3"}); len(got) != 0 {
		t.Fatalf("another organization's actor = %v", got)
	}
}

